using System.Text.Json;using HRM.Models;using HRM.WorkPlanning.Abstractions;using Microsoft.EntityFrameworkCore;
namespace HRM.WorkPlanning.Services;
public sealed class WorkforceConstraintService(IDbContextFactory<HrmTeContext> factory,IWorkforcePolicyResolver policies):IWorkforceConstraintService{public async Task<IReadOnlyList<WorkforceConstraintViolation>>ValidateAsync(int rosterVersionId,CancellationToken ct=default){await using var db=await factory.CreateDbContextAsync(ct);var rows=await db.DutyAssignments.AsNoTracking().Where(x=>x.DutyOccurrence.WorkforceRosterVersionId==rosterVersionId&&x.Status=="Assigned").Select(x=>new{x.IndividualId,x.JobId,x.DutyOccurrenceId,x.DutyOccurrence.DutyTypeId,x.DutyOccurrence.StartAt,x.DutyOccurrence.EndAt,x.DutyOccurrence.WorkforceRosterVersion.WorkforceRoster.OrganisationId}).ToListAsync(ct);var result=new List<WorkforceConstraintViolation>();foreach(var group in rows.GroupBy(x=>x.IndividualId)){var ordered=group.OrderBy(x=>x.StartAt).ToList();for(var i=1;i<ordered.Count;i++){var policy=await policies.ResolveAsync(new(ordered[i].OrganisationId,DateOnly.FromDateTime(ordered[i].StartAt),ordered[i].JobId,ordered[i].IndividualId,ordered[i].DutyTypeId),ct);foreach(var p in policy){using var doc=JsonDocument.Parse(p.RulesJson);if(!doc.RootElement.TryGetProperty("MIN_REST_BETWEEN_SHIFTS",out var rule)||!rule.TryGetProperty("minimumMinutes",out var minutes))continue;var rest=(ordered[i].StartAt-ordered[i-1].EndAt).TotalMinutes;if(rest<minutes.GetInt32()){var severity=rule.TryGetProperty("enforcement",out var enforcement)?enforcement.GetString()??"HARD_BLOCK":"HARD_BLOCK";result.Add(new("MIN_REST_BETWEEN_SHIFTS",severity,$"Staff member {group.Key} has only {rest:0} rest minutes before duty {ordered[i].DutyOccurrenceId}.",ordered[i].DutyOccurrenceId,group.Key));}}}foreach(var row in group){var policy=await policies.ResolveAsync(new(row.OrganisationId,DateOnly.FromDateTime(row.StartAt),row.JobId,row.IndividualId,row.DutyTypeId),ct);foreach(var p in policy){using var doc=JsonDocument.Parse(p.RulesJson);if(!doc.RootElement.TryGetProperty("QUALIFICATION_RULE",out var rule)||!rule.TryGetProperty("requiredJobMatrixIds",out var required)||required.ValueKind!=JsonValueKind.Array)continue;var matrices=required.EnumerateArray().Where(x=>x.TryGetInt32(out _)).Select(x=>x.GetInt32()).ToArray();if(matrices.Length==0)continue;var qualified=await db.JobPositions.AsNoTracking().Where(x=>x.JobId==row.JobId&&x.FromDate<=row.StartAt&&(!x.ToDate.HasValue||x.ToDate>=row.StartAt)).Join(db.Positions.AsNoTracking(),x=>x.PositionId,x=>x.PositionId,(x,p)=>p.PositionMatrixId).Join(db.PositionMatrices.AsNoTracking(),x=>x,x=>x.PositionMatrixId,(x,m)=>m.JobMatrixId).AnyAsync(x=>matrices.Contains(x),ct);if(!qualified){var severity=rule.TryGetProperty("enforcement",out var enforcement)?enforcement.GetString()??"HARD_BLOCK":"HARD_BLOCK";result.Add(new("QUALIFICATION_RULE",severity,$"Staff member {row.IndividualId} does not hold a position mapped to a required qualification matrix for duty {row.DutyOccurrenceId}.",row.DutyOccurrenceId,row.IndividualId));}}}}return result;}}
